package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.edge;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePlanExecutionProfile.Mode;
import org.junit.jupiter.api.Test;

/** The physical quote follows the independent OPTIONAL build and its candidate replay. */
class NativeOptionalCostRegressionTest {

	@Test
	void independentRightSourceIsPricedOnceInTheEntryFrame() {
		StatsSource source = new StatsSource(100_000L).predicate(1L, 3D, 3_000L)
				.predicate(2L, 3D, 3_000L);
		RowState row = row(source);
		try {
			PatternPlan left = edge(0, 1L, 1, 9_000D);
			PatternPlan right = edge(0, 2L, 2, 9_000D);
			LeftJoinPlan optional = new LeftJoinPlan(left, right, new int[] { 0 });
			LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(optional, row, 0L, Mode.SEQUENTIAL);
			double sourceRows = LmdbNativeCostVectors.pattern(left, row, 0L).expected(Feature.SCANNED_ROW)
					+ LmdbNativeCostVectors.pattern(right, row, 0L).expected(Feature.SCANNED_ROW);
			assertThat(quote.expected(Feature.SCANNED_ROW))
					.as("one RHS build reads the entry frame, rather than a bound source probe per left row")
					.isEqualTo(sourceRows);
			assertThat(quote.expected(Feature.DECODED_ROW))
					.as("right rows and compatible candidates have replay/codec work")
					.isPositive();
			assertThat(quote.expected(Feature.MEMBERSHIP_TEST))
					.as("candidate compatibility is checked for each probe")
					.isPositive();
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void everyExecutionTierUsesTheIndependentEntryMask() {
		StatsSource source = new StatsSource(100_000L).predicate(1L, 3D, 3_000L)
				.predicate(2L, 3D, 3_000L);
		RowState row = row(source);
		try {
			PatternPlan left = edge(0, 1L, 1, 9_000D);
			PatternPlan right = edge(0, 2L, 2, 9_000D);
			LeftJoinPlan optional = new LeftJoinPlan(left, right, new int[] { 0 });
			for (Mode mode : Mode.values()) {
				LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.profile(optional, row, 0L, mode);
				assertThat(quote.expected(Feature.SCANNED_ROW)).as("mode %s", mode).isEqualTo(18_000D);
				assertThat(quote.high(Feature.SCANNED_ROW)).isInfinite();
			}
		} finally {
			row.memoryScope.close();
		}
	}
}
